/* @autogenerated */
import { Component, inject } from '@angular/core';
import { User } from 'app/features/identity/user/model/user.model';
import { UserRepository } from 'app/features/identity/user/repository/user-repository.service';
import { ConfirmSelectionAction } from 'app/shared/toolkit/action/confirm-selection-action';

@Component({ selector: 'user-view-unlock-selection-action', standalone: false, template: '' })
export class UserViewUnlockSelectionActionComponent extends ConfirmSelectionAction<User> {
  readonly name = 'unlockSelection';
  protected readonly scope = 'identity/user';
  protected readonly repository = inject(UserRepository);

  protected runSelection(items: User[]) {
    return this.repository.unlockSelection({ uids: items.map((item) => item.uid) });
  }
}
